void cb_init(cb_t *cb, uint8_t *buffer, size_t size) {
    if (!cb) return;
    cb->buffer = buffer;
    cb->size = size;
    cb->head = cb->tail = cb->count = 0;
}

bool cb_push(cb_t *cb, uint8_t data) {
    if (!cb || cb_is_full(cb)) return false;
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % cb->size;
    cb->count++;
    return true;
}

bool cb_pop(cb_t *cb, uint8_t *out) {
    if (!cb || !out || cb_is_empty(cb)) return false;
    *out = cb->buffer[cb->tail];
    cb->tail = (cb->tail + 1) % cb->size;
    cb->count--;
    return true;
}

bool cb_is_empty(const cb_t *cb) {
    if (!cb) return true;
    return cb->count == 0;
}

bool cb_is_full(const cb_t *cb) {
    if (!cb) return false;
    return cb->count == cb->size;
}

size_t cb_count(const cb_t *cb) {
    return cb ? cb->count : 0;
}

void cb_flush(cb_t *cb) {
    if (!cb) return;
    cb->head = cb->tail = cb->count = 0;
}

bool cbp2_init(cbp2_t *q, uint8_t *buf, uint32_t size) {
    if (!q || !buf) return false;
    if (size < 2 || (size & (size - 1)) != 0) return false;  // pow2
    q->buf = buf; q->size = size; q->mask = size - 1;
    q->head = q->tail = 0;
    return true;
}
uint32_t cbp2_count(const cbp2_t *q) {
    return q ? q->head - q->tail : 0;   // unsigned 뺄셈
}
bool cbp2_push(cbp2_t *q, uint8_t data) {
    if (!q || cbp2_count(q) == q->size) return false;
    q->buf[q->head & q->mask] = data;   // % 대신 & mask
    q->head++;
    return true;
}
bool cbp2_pop(cbp2_t *q, uint8_t *out) {
    if (!q || !out || q->head == q->tail) return false;
    *out = q->buf[q->tail & q->mask];
    q->tail++;
    return true;
}

bool spsc_init(spsc_t *q, uint8_t *buf, uint32_t size) {
    if (!q || !buf || size < 2 || (size & (size-1))) return false;
    q->buf = buf; q->size = size; q->mask = size - 1;
    atomic_init(&q->head, 0u); atomic_init(&q->tail, 0u);
    return true;
}
bool spsc_push(spsc_t *q, uint8_t data) {   // 생산자 컨텍스트만
    if (!q) return false;
    uint32_t h = atomic_load_explicit(&q->head, memory_order_relaxed);
    uint32_t t = atomic_load_explicit(&q->tail, memory_order_acquire);
    if (((h + 1) & q->mask) == (t & q->mask)) return false;   // full
    q->buf[h & q->mask] = data;                                // 1) 데이터
    atomic_store_explicit(&q->head, h + 1, memory_order_release); // 2) 공개
    return true;
}
bool spsc_pop(spsc_t *q, uint8_t *out) {   // 소비자 컨텍스트만
    if (!q || !out) return false;
    uint32_t t = atomic_load_explicit(&q->tail, memory_order_relaxed);
    uint32_t h = atomic_load_explicit(&q->head, memory_order_acquire);
    if (h == t) return false;                                  // empty
    *out = q->buf[t & q->mask];
    atomic_store_explicit(&q->tail, t + 1, memory_order_release);
    return true;
}

void mpmc_init(mpmc_t *q, uint8_t *buf, size_t size) {
    q->buf = buf; q->size = size; q->head = q->tail = q->count = 0;
    pthread_mutex_init(&q->m, NULL);
    pthread_cond_init(&q->not_full, NULL);
    pthread_cond_init(&q->not_empty, NULL);
}
void mpmc_push(mpmc_t *q, uint8_t data) {
    pthread_mutex_lock(&q->m);
    while (q->count == q->size)
        pthread_cond_wait(&q->not_full, &q->m);   // while!
    q->buf[q->head] = data;
    q->head = (q->head + 1) % q->size;
    q->count++;
    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->m);
}
uint8_t mpmc_pop(mpmc_t *q) {
    pthread_mutex_lock(&q->m);
    while (q->count == 0)
        pthread_cond_wait(&q->not_empty, &q->m);
    uint8_t data = q->buf[q->tail];
    q->tail = (q->tail + 1) % q->size;
    q->count--;
    pthread_cond_signal(&q->not_full);
    pthread_mutex_unlock(&q->m);
    return data;
}
void mpmc_destroy(mpmc_t *q) {
    pthread_mutex_destroy(&q->m);
    pthread_cond_destroy(&q->not_full);
    pthread_cond_destroy(&q->not_empty);
}
